    VALUES ('2eaef4cf-c716-fd25-7cc8-c1bdfb593d8c','bdd2a46a-0011-1af0-6f1d-cfe3a1101fcd',N'Báo cáo tổng hợp khảo sát thực phẩm chức năng',N'KSTPCN-2026-01/BC','2026-10-12',N'DA_CHOT','2026-10-12T09:00:00',N'Dữ liệu phản ánh có nhận thức và mức độ phối hợp nhất định trong quản lý thực phẩm chức năng.',N'Một số nội dung còn khó kiểm soát như quảng cáo trên môi trường mạng, nguồn gốc sản phẩm và cơ sở dữ liệu quản lý.',N'Tăng cường hậu kiểm, hoàn thiện pháp luật, đẩy mạnh tuyên truyền và ứng dụng công nghệ thông tin.',N'uploads/sample-data/khao-sat-thuc-pham-chuc-nang/bao-cao/bao-cao-khao-sat-thuc-pham-chuc-nang.txt',N'bao-cao-khao-sat-thuc-pham-chuc-nang.txt','2026-10-12T09:00:00',@Now,CONVERT(nvarchar(64),@Actor),0);
